import Link from "next/link"
import { ArrowRight } from "lucide-react"
import { Button } from "@ui/components/button"
import { Container } from "@ui/components/layout"
import { STORE_CONTAINER_INSET_WIDE, STORE_CONTAINER_MAX_DEFAULT } from "@ui/lib/layout-shell"
import type { PublicEventCategoryItem, PublicEventItem } from "@/lib/public-events"
import { EventRowCard } from "./event-row-card"

export type CategoryWithEvents = {
  category: PublicEventCategoryItem
  events: PublicEventItem[]
}

type EventsCategorySectionsProps = {
  sections: CategoryWithEvents[]
  buildCategoryHref?: (categorySlug: string) => string
  onCategorySelect?: (categorySlug: string) => void
  embedded?: boolean
}

export function EventsCategorySections({
  sections,
  buildCategoryHref,
  onCategorySelect,
  embedded = false,
}: EventsCategorySectionsProps) {
  const visible = sections.filter((s) => s.events.length > 0)

  if (visible.length === 0) return null

  const content = (
    <div className="space-y-10">
        <div className="space-y-1">
          <h2 className="text-xl font-bold text-foreground sm:text-2xl">Danh mục sự kiện</h2>
          <p className="text-sm text-muted-foreground">
            Khám phá sự kiện theo từng lĩnh vực tại Trường Đại học Ngân hàng TP. HCM.
          </p>
        </div>

        {visible.map(({ category, events }) => (
          <div key={category.id} className="space-y-4">
            <div className="flex items-center justify-between gap-4 border-b border-border pb-2">
              <h3 className="text-lg font-bold text-foreground">{category.name}</h3>
              {onCategorySelect ? (
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="group shrink-0 rounded-lg text-primary"
                  onClick={() => onCategorySelect(category.slug)}
                >
                  Xem thêm
                  <ArrowRight className="size-4 transition-transform group-hover:translate-x-0.5" />
                </Button>
              ) : buildCategoryHref ? (
                <Link href={buildCategoryHref(category.slug)}>
                  <Button variant="ghost" size="sm" className="group shrink-0 rounded-lg text-primary">
                    Xem thêm
                    <ArrowRight className="size-4 transition-transform group-hover:translate-x-0.5" />
                  </Button>
                </Link>
              ) : null}
            </div>
            <div className="grid gap-3">
              {events.slice(0, 5).map((event) => (
                <EventRowCard key={event.id} event={event} compact />
              ))}
            </div>
          </div>
        ))}
    </div>
  )

  if (embedded) {
    return (
      <section className="rounded-2xl border border-border/80 bg-card/80 p-5 sm:p-6">
        {content}
      </section>
    )
  }

  return (
    <section className="border-b border-border bg-background py-10 sm:py-12">
      <Container max={STORE_CONTAINER_MAX_DEFAULT} className={`${STORE_CONTAINER_INSET_WIDE}`}>
        {content}
      </Container>
    </section>
  )
}

"use client"

import {
  CalendarDays,
  ClipboardCheck,
  FilterX,
  Layers,
  SlidersHorizontal,
  X,
} from "lucide-react"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import { cn } from "@ui/lib/utils"
import { EVENT_STATUS_LABELS, type PublicEventCategoryItem } from "@/lib/public-events"
import type { EventsListQuery } from "@/lib/events-list-query"

type EventsFilterSidebarProps = {
  query: EventsListQuery
  categories: PublicEventCategoryItem[]
  onApplyQuery: (next: Partial<EventsListQuery>) => void
  onResetFilters: () => void
}

const STATUS_OPTIONS = [
  { key: "", label: "Tất cả", icon: CalendarDays },
  ...Object.entries(EVENT_STATUS_LABELS).map(([key, label]) => ({
    key,
    label,
    icon: CalendarDays,
  })),
] as const

const REGISTERABLE_OPTIONS = [
  { key: false, label: "Tất cả sắp diễn ra" },
  { key: true, label: "Có thể đăng ký" },
] as const

function EventsFilterPill({
  active,
  label,
  onClick,
}: {
  active: boolean
  label: string
  onClick: () => void
}) {
  return (
    <Badge
      render={<button type="button" onClick={onClick} />}
      variant={active ? "promo" : "muted"}
      size="sm"
      className="cursor-pointer"
    >
      {label}
    </Badge>
  )
}

export function EventsFilterSidebar({
  query,
  categories,
  onApplyQuery,
  onResetFilters,
}: EventsFilterSidebarProps) {
  const {
    filter: activeFilter = "",
    categorySlug: activeCategorySlug,
    search,
    registerable,
  } = query
  const showRegisterableOptions = activeFilter === "upcoming"

  const activeChips: { key: string; label: string; onRemove: () => void }[] = []
  if (activeFilter) {
    activeChips.push({
      key: "filter",
      label: EVENT_STATUS_LABELS[activeFilter as keyof typeof EVENT_STATUS_LABELS] ?? activeFilter,
      onRemove: () => onApplyQuery({ filter: "", page: 1, registerable: false }),
    })
  }
  if (registerable) {
    activeChips.push({
      key: "registerable",
      label: "Có thể đăng ký",
      onRemove: () => onApplyQuery({ registerable: false, page: 1 }),
    })
  }
  if (activeCategorySlug) {
    const catName =
      categories.find((c) => c.slug === activeCategorySlug)?.name ?? activeCategorySlug
    activeChips.push({
      key: "category",
      label: `DM: ${catName}`,
      onRemove: () => onApplyQuery({ categorySlug: "", page: 1 }),
    })
  }
  if (search?.trim()) {
    const term = search.trim()
    activeChips.push({
      key: "search",
      label: `“${term.slice(0, 24)}${term.length > 24 ? "…" : ""}”`,
      onRemove: () => onApplyQuery({ search: "", page: 1 }),
    })
  }

  const hasActiveFilters = activeChips.length > 0

  return (
    <aside
      className="w-full shrink-0 lg:sticky lg:top-28 lg:w-72 lg:max-h-[calc(100vh-6.5rem)] lg:overflow-y-auto xl:w-80"
      aria-label="Bộ lọc sự kiện"
    >
      <div className="space-y-4 rounded-2xl border border-border/80 bg-card p-4 shadow-sm ring-1 ring-black/[0.03] sm:p-5">
        <div>
          <p className="mb-3 text-xs font-bold uppercase tracking-widest text-muted-foreground">
            Trạng thái
          </p>
          <nav
            className="flex gap-2 overflow-x-auto pb-1 [-ms-overflow-style:none] [scrollbar-width:none] lg:flex-col lg:gap-1 lg:overflow-visible lg:pb-0 [&::-webkit-scrollbar]:hidden"
            aria-label="Lọc theo trạng thái"
          >
            {STATUS_OPTIONS.map((option) => {
              const Icon = option.icon
              const isActive = activeFilter === option.key
              return (
                <button
                  key={option.key || "all"}
                  type="button"
                  onClick={() =>
                    onApplyQuery({
                      filter: option.key,
                      page: 1,
                      registerable: option.key === "upcoming" ? registerable : false,
                    })
                  }
                  className={cn(
                    "flex w-full shrink-0 items-center gap-2 rounded-xl border px-3 py-2.5 text-left text-sm font-bold transition-all lg:px-3.5",
                    isActive
                      ? "border-primary bg-primary text-primary-foreground shadow-sm"
                      : "border-border/60 bg-background text-muted-foreground hover:border-primary/20 hover:bg-muted/40",
                  )}
                >
                  <Icon className="size-4 shrink-0" aria-hidden />
                  <span className="truncate">{option.label}</span>
                </button>
              )
            })}
          </nav>
        </div>

        {showRegisterableOptions ? (
          <div className="border-t border-border/50 pt-4">
            <div className="mb-3 flex items-center gap-2">
              <ClipboardCheck className="size-4 shrink-0 text-primary" aria-hidden />
              <span className="text-sm font-bold text-foreground">Đăng ký</span>
            </div>
            <div className="flex flex-wrap gap-2">
              {REGISTERABLE_OPTIONS.map((option) => (
                <EventsFilterPill
                  key={String(option.key)}
                  active={registerable === option.key}
                  label={option.label}
                  onClick={() => onApplyQuery({ registerable: option.key, page: 1 })}
                />
              ))}
            </div>
          </div>
        ) : null}

        {categories.length > 0 ? (
          <div className="border-t border-border/50 pt-4">
            <div className="mb-3 flex items-center gap-2">
              <Layers className="size-4 shrink-0 text-primary" aria-hidden />
              <span className="text-sm font-bold text-foreground">Danh mục</span>
            </div>
            <nav
              className="flex max-h-52 flex-col gap-1 overflow-y-auto pr-1 lg:max-h-64"
              aria-label="Lọc theo danh mục"
            >
              <button
                type="button"
                onClick={() => onApplyQuery({ categorySlug: "", page: 1 })}
                className={cn(
                  "rounded-xl px-3 py-2.5 text-left text-sm font-bold transition-colors",
                  !activeCategorySlug
                    ? "bg-primary text-primary-foreground"
                    : "text-muted-foreground hover:bg-muted/50 hover:text-foreground",
                )}
              >
                Tất cả danh mục
              </button>
              {categories.map((cat) => (
                <button
                  key={cat.id}
                  type="button"
                  onClick={() => onApplyQuery({ categorySlug: cat.slug, page: 1 })}
                  className={cn(
                    "rounded-xl px-3 py-2.5 text-left text-sm font-bold transition-colors",
                    activeCategorySlug === cat.slug
                      ? "bg-primary text-primary-foreground"
                      : "text-muted-foreground hover:bg-muted/50 hover:text-foreground",
                  )}
                >
                  {cat.name}
                </button>
              ))}
            </nav>
          </div>
        ) : null}

        {hasActiveFilters ? (
          <div className="space-y-2 border-t border-border/50 pt-4">
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-2">
                <SlidersHorizontal className="size-4 text-primary" aria-hidden />
                <Badge variant="muted" size="sm">
                  Đang lọc
                </Badge>
              </div>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="h-8 gap-1 text-xs text-muted-foreground"
                onClick={onResetFilters}
              >
                <FilterX className="size-3.5" />
                Xóa hết
              </Button>
            </div>
            <div className="flex flex-wrap gap-2">
              {activeChips.map((chip) => (
                <Badge
                  key={chip.key}
                  render={<button type="button" onClick={chip.onRemove} />}
                  variant="category"
                  size="sm"
                  shape="pill"
                  className="cursor-pointer gap-1"
                >
                  {chip.label}
                  <X className="size-3" aria-hidden />
                </Badge>
              ))}
            </div>
          </div>
        ) : null}
      </div>
    </aside>
  )
}

"use client"

import { SearchX } from "lucide-react"
import { Button } from "@ui/components/button"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@ui/components/empty"
import {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
} from "@ui/components/pagination"
import { Text } from "@ui/components/typography"
import { cn } from "@ui/lib/utils"
import { EventCatalogCard } from "./event-catalog-card"
import type { EventsListQuery } from "@/lib/events-list-query"
import type { PublicEventItem } from "@/lib/public-events"

type EventsListPanelProps = {
  query: EventsListQuery
  listTitle: string
  listSubtitle: string
  events: PublicEventItem[]
  meta: { page: number; totalPages: number; total: number }
  pagerItems: Array<number | "ellipsis">
  isLoading: boolean
  isFetching: boolean
  registerable: boolean
  search: string
  onApplyQuery: (next: Partial<EventsListQuery>) => void
  onResetFilters: () => void
}

function EventsListSkeleton() {
  return (
    <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">
      {Array.from({ length: 6 }).map((_, index) => (
        <div
          key={index}
          className="h-80 animate-pulse rounded-2xl bg-muted/40"
          aria-hidden
        />
      ))}
    </div>
  )
}

export function EventsListPanel({
  query,
  listTitle,
  listSubtitle,
  events,
  meta,
  pagerItems,
  isLoading,
  isFetching,
  registerable,
  search,
  onApplyQuery,
  onResetFilters,
}: EventsListPanelProps) {
  const { limit } = query

  return (
    <div className="space-y-5">
      <div className="flex flex-col gap-3 rounded-xl border border-border/60 bg-muted/10 px-4 py-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="space-y-0.5">
          <h2 className="text-lg font-bold text-foreground sm:text-xl">{listTitle}</h2>
          <Text variant="small" className="text-muted-foreground">
            {listSubtitle}
            {isFetching && !isLoading ? (
              <span className="ml-2 text-xs text-primary">(đang cập nhật…)</span>
            ) : null}
          </Text>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-1 rounded-lg border border-border bg-background/80 p-1">
            {[6, 12, 24].map((limitOption) => (
              <Button
                key={limitOption}
                type="button"
                variant={limitOption === limit ? "default" : "ghost"}
                size="sm"
                className="h-8 rounded-md px-3 text-xs sm:text-sm"
                disabled={isFetching && limitOption === limit}
                onClick={() => onApplyQuery({ limit: limitOption, page: 1 })}
              >
                {limitOption}/trang
              </Button>
            ))}
          </div>
        </div>
      </div>

      <div
        className={cn(
          "relative transition-opacity duration-200",
          isFetching && !isLoading && "opacity-60",
        )}
      >
        {isLoading ? (
          <EventsListSkeleton />
        ) : events.length > 0 ? (
          <>
            <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">
              {events.map((event) => (
                <EventCatalogCard key={event.id} event={event} />
              ))}
            </div>

            {meta.totalPages > 1 ? (
              <Pagination className="justify-center pt-2">
                <PaginationContent>
                  <PaginationItem>
                    <PaginationPrevious
                      href="#"
                      text="Trước"
                      aria-disabled={meta.page <= 1 || isFetching}
                      className={cn(
                        meta.page <= 1 || isFetching
                          ? "pointer-events-none opacity-40"
                          : "cursor-pointer",
                      )}
                      onClick={(event) => {
                        event.preventDefault()
                        if (meta.page <= 1 || isFetching) return
                        onApplyQuery({ page: Math.max(1, meta.page - 1) })
                      }}
                    />
                  </PaginationItem>
                  {pagerItems.map((item, index) => (
                    <PaginationItem key={`${item}-${index}`}>
                      {item === "ellipsis" ? (
                        <PaginationEllipsis />
                      ) : (
                        <PaginationLink
                          href="#"
                          isActive={item === meta.page}
                          className={isFetching ? "pointer-events-none" : "cursor-pointer"}
                          onClick={(event) => {
                            event.preventDefault()
                            if (isFetching) return
                            onApplyQuery({ page: item })
                          }}
                        >
                          {item}
                        </PaginationLink>
                      )}
                    </PaginationItem>
                  ))}
                  <PaginationItem>
                    <PaginationNext
                      href="#"
                      text="Sau"
                      aria-disabled={meta.page >= meta.totalPages || isFetching}
                      className={cn(
                        meta.page >= meta.totalPages || isFetching
                          ? "pointer-events-none opacity-40"
                          : "cursor-pointer",
                      )}
                      onClick={(event) => {
                        event.preventDefault()
                        if (meta.page >= meta.totalPages || isFetching) return
                        onApplyQuery({
                          page: Math.min(meta.totalPages, meta.page + 1),
                        })
                      }}
                    />
                  </PaginationItem>
                </PaginationContent>
              </Pagination>
            ) : null}
          </>
        ) : (
          <Empty className="rounded-2xl border border-dashed bg-card/60 py-12">
            <EmptyHeader>
              <EmptyMedia variant="icon">
                <SearchX className="size-5" />
              </EmptyMedia>
              <EmptyTitle>Không tìm thấy sự kiện phù hợp</EmptyTitle>
              <EmptyDescription>
                {search
                  ? "Thử từ khóa khác hoặc bỏ bộ lọc để xem thêm sự kiện."
                  : registerable
                    ? "Thử bỏ lọc đăng ký hoặc chọn trạng thái khác."
                    : "Thử đổi bộ lọc hoặc chọn danh mục khác."}
              </EmptyDescription>
            </EmptyHeader>
            <EmptyContent>
              <Button
                type="button"
                variant="outline"
                className="rounded-lg"
                onClick={onResetFilters}
              >
                Đặt lại bộ lọc
              </Button>
            </EmptyContent>
          </Empty>
        )}
      </div>
    </div>
  )
}

"use client"

import { useCallback, useMemo } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { Container, Page, PageContent } from "@ui/components/layout"
import { STORE_CONTAINER_INSET_WIDE, STORE_CONTAINER_MAX_DEFAULT } from "@ui/lib/layout-shell"
import { EventsCategorySections } from "./events-category-sections"
import { EventsCodePanel } from "./events-code-panel"
import { EventsFeaturedStrip } from "./events-featured-strip"
import { EventsFilterSidebar } from "./events-filter-sidebar"
import { EventsListPanel } from "./events-list-panel"
import { EventsPageBanner } from "./events-page-banner"
import {
  buildEventsHref,
  parseEventsListQuery,
  type EventsListQuery,
} from "@/lib/events-list-query"
import { EVENT_STATUS_LABELS } from "@/lib/public-events"
import {
  useEventCategorySections,
  useFeaturedPublicEvents,
  usePublicEventCategories,
  usePublicEventsList,
} from "@/hooks/use-events-catalog"

function buildPaginationItems(
  currentPage: number,
  totalPages: number,
): Array<number | "ellipsis"> {
  if (totalPages <= 7) {
    return Array.from({ length: totalPages }, (_, index) => index + 1)
  }
  const pages = new Set<number>([
    1,
    2,
    totalPages - 1,
    totalPages,
    currentPage - 1,
    currentPage,
    currentPage + 1,
  ])
  const sorted = Array.from(pages)
    .filter((page) => page >= 1 && page <= totalPages)
    .sort((a, b) => a - b)
  const output: Array<number | "ellipsis"> = []
  for (let index = 0; index < sorted.length; index += 1) {
    const value = sorted[index]
    const previous = sorted[index - 1]
    if (previous && value - previous > 1) output.push("ellipsis")
    output.push(value)
  }
  return output
}

export function EventsPageClient() {
  const router = useRouter()
  const searchParams = useSearchParams()

  const query = useMemo(
    () => parseEventsListQuery(searchParams),
    [searchParams],
  )

  const applyQuery = useCallback(
    (next: Partial<EventsListQuery>) => {
      const href = buildEventsHref(query, next)
      router.replace(href, { scroll: false })
    },
    [query, router],
  )

  const resetFilters = useCallback(() => {
    router.replace("/su-kien", { scroll: false })
  }, [router])

  const { data: categories = [] } = usePublicEventCategories()

  const showFeatured = query.page === 1 && !query.search
  const showCategoryBrowse =
    query.page === 1 &&
    !query.categorySlug &&
    !query.filter &&
    !query.search &&
    !query.registerable

  const { data: featuredEvents = [] } = useFeaturedPublicEvents(showFeatured)

  const {
    data: listData,
    isLoading: isListLoading,
    isFetching: isListFetching,
  } = usePublicEventsList(query)

  const validFilter = listData?.validFilter ?? "all"
  const { data: categorySections = [] } = useEventCategorySections(
    categories,
    validFilter,
    showCategoryBrowse,
  )

  const events = listData?.events ?? []
  const meta = listData?.meta ?? {
    page: query.page,
    totalPages: 1,
    total: 0,
    limit: query.limit,
  }
  const pagerItems = buildPaginationItems(meta.page, meta.totalPages)

  const listTitle = query.search
    ? "Kết quả tìm kiếm"
    : query.categorySlug
      ? categories.find((c) => c.slug === query.categorySlug)?.name ?? "Danh sách sự kiện"
      : query.registerable
        ? "Sắp diễn ra · Có thể đăng ký"
        : validFilter !== "all"
          ? EVENT_STATUS_LABELS[validFilter]
          : "Tất cả sự kiện"

  const listSubtitle = query.search
    ? meta.total > 0
      ? `${meta.total} kết quả cho “${query.search}” · Trang ${meta.page}/${meta.totalPages}`
      : `Không có kết quả cho “${query.search}”`
    : meta.total > 0
      ? `${meta.total} sự kiện · Trang ${meta.page}/${meta.totalPages}`
      : query.registerable
        ? "Không có sự kiện sắp diễn ra đang mở đăng ký."
        : "Chưa có sự kiện phù hợp với bộ lọc hiện tại"

  return (
    <Page className="bg-[radial-gradient(circle_at_top_left,hsl(var(--primary)/0.06),transparent_34%),linear-gradient(180deg,hsl(var(--muted)/0.35),transparent_28%)]">
      <PageContent className="p-0">
        <EventsPageBanner
          query={query}
          search={query.search ?? ""}
          onApplyQuery={applyQuery}
        />

        <section className="py-8 sm:py-10">
          <Container
            max={STORE_CONTAINER_MAX_DEFAULT}
            className={`${STORE_CONTAINER_INSET_WIDE} space-y-6`}
          >
            {showFeatured && featuredEvents.length > 0 ? (
              <EventsFeaturedStrip events={featuredEvents} />
            ) : null}

            <div className="flex flex-col gap-6 lg:flex-row lg:items-start lg:gap-8">
              <EventsFilterSidebar
                query={query}
                categories={categories}
                onApplyQuery={applyQuery}
                onResetFilters={resetFilters}
              />

              <div className="min-w-0 flex-1 space-y-5">
                {showCategoryBrowse ? (
                  <EventsCategorySections
                    sections={categorySections}
                    onCategorySelect={(slug) =>
                      applyQuery({ categorySlug: slug, page: 1 })
                    }
                    embedded
                  />
                ) : null}

                <EventsListPanel
                  query={query}
                  listTitle={listTitle}
                  listSubtitle={listSubtitle}
                  events={events}
                  meta={meta}
                  pagerItems={pagerItems}
                  isLoading={isListLoading}
                  isFetching={isListFetching}
                  registerable={!!query.registerable}
                  search={query.search ?? ""}
                  onApplyQuery={applyQuery}
                  onResetFilters={resetFilters}
                />
              </div>
            </div>
          </Container>
        </section>

        <EventsCodePanel />
      </PageContent>
    </Page>
  )
}

"use client"

import { useState } from "react"
import { QueryClientProvider } from "@tanstack/react-query"
import { createHubQueryClient } from "@workspace/query-client"

export function EventsQueryProvider({ children }: { children: React.ReactNode }) {
  const [client] = useState(() =>
    createHubQueryClient({
      defaultOptions: {
        queries: {
          refetchOnWindowFocus: false,
          retry: 1,
        },
      },
    }),
  )

  return <QueryClientProvider client={client}>{children}</QueryClientProvider>
}

"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { Search, X } from "lucide-react"
import { Button } from "@ui/components/button"
import { Input } from "@ui/components/input"
import {
  buildEventsHref,
  type EventsListQuery,
} from "@/lib/events-list-query"

type EventsSearchFormProps = {
  initialSearch: string
  query: EventsListQuery
  tone?: "default" | "banner"
  onApplyQuery?: (next: Partial<EventsListQuery>) => void
}

export function EventsSearchForm({
  initialSearch,
  query,
  tone = "default",
  onApplyQuery,
}: EventsSearchFormProps) {
  const router = useRouter()
  const [value, setValue] = useState(initialSearch)

  useEffect(() => {
    setValue(initialSearch)
  }, [initialSearch])

  const navigate = (term: string) => {
    const trimmed = term.trim()
    if (onApplyQuery) {
      onApplyQuery({ search: trimmed || undefined, page: 1 })
      return
    }
    router.replace(
      buildEventsHref(query, { search: trimmed || undefined, page: 1 }),
      { scroll: false },
    )
  }

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault()
    navigate(value)
  }

  return (
    <form onSubmit={handleSubmit} className="relative w-full">
      <Search
        className={
          tone === "banner"
            ? "pointer-events-none absolute top-1/2 left-3.5 size-5 -translate-y-1/2 text-muted-foreground"
            : "pointer-events-none absolute top-1/2 left-3.5 size-4 -translate-y-1/2 text-muted-foreground"
        }
        aria-hidden
      />
      <Input
        value={value}
        onChange={(event) => setValue(event.target.value)}
        placeholder="Tìm theo tên sự kiện, địa điểm, ban tổ chức..."
        className={
          tone === "banner"
            ? "h-11 w-full rounded-xl border-white/20 bg-white pl-11 pr-24 text-base text-foreground shadow-sm"
            : "h-11 rounded-xl border-border/80 bg-card pl-10 pr-24 text-sm shadow-sm"
        }
        aria-label="Tìm kiếm sự kiện"
      />
      <div className="absolute top-1/2 right-1.5 flex -translate-y-1/2 items-center gap-1">
        {value.trim() ? (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-8 rounded-lg text-muted-foreground"
            onClick={() => {
              setValue("")
              navigate("")
            }}
            aria-label="Xóa tìm kiếm"
          >
            <X className="size-4" />
          </Button>
        ) : null}
        <Button type="submit" size="sm" className="h-8 rounded-lg px-3 text-xs">
          Tìm
        </Button>
      </div>
    </form>
  )
}

