import { ImageIcon } from "lucide-react"
import { cn } from "@ui/lib/utils"
import { getPosterUrl } from "@/lib/public-events"

type EventPosterProps = {
  poster?: unknown
  alt: string
  className?: string
  imageClassName?: string
  placeholderClassName?: string
  aspectClassName?: string
  priority?: boolean
  overlay?: React.ReactNode
  showBottomGradient?: boolean
}

/**
 * Poster sự kiện — dùng URL API trực tiếp (giống admin), không qua next/image optimizer.
 */
export function EventPoster({
  poster,
  alt,
  className,
  imageClassName,
  placeholderClassName = "size-10 text-muted-foreground/40",
  aspectClassName = "aspect-[16/10] w-full",
  priority = false,
  overlay,
  showBottomGradient = false,
}: EventPosterProps) {
  const posterUrl = getPosterUrl(poster)

  return (
    <div className={cn("relative overflow-hidden bg-muted", aspectClassName, className)}>
      {posterUrl ? (
        <>
          <img
            src={posterUrl}
            alt={alt}
            loading={priority ? "eager" : "lazy"}
            decoding="async"
            className={cn(
              "absolute inset-0 h-full w-full object-cover",
              imageClassName,
            )}
          />
          {showBottomGradient ? (
            <div
              className="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-transparent"
              aria-hidden
            />
          ) : null}
        </>
      ) : (
        <div className="absolute inset-0 flex items-center justify-center bg-muted">
          <ImageIcon className={placeholderClassName} aria-hidden />
        </div>
      )}
      {overlay}
    </div>
  )
}

src/components/shared/header-access-clus.content:
"use client"

import { usePathname } from "next/navigation"
import { useEffect, useSyncExternalStore } from "react"
import { HeaderAccountMenu } from "@/components/shared/header-account-menu"
import { HeaderAuth } from "@/components/shared/header-auth"
import { HeaderStaffAccountMenu } from "@/components/shared/header-staff-account-menu"
import { useAdminSession } from "@/components/shared/use-admin-session"
import {
  HeaderGuestAccessDropdown,
  HeaderGuestAccessOptions,
} from "@/components/shared/header-guest-access-menu"
import {
  getActiveCheckinSessionKind,
  readEventSession,
  subscribeEventSession,
} from "@/lib/event-auth"

function useEventSession() {
  return useSyncExternalStore(
    subscribeEventSession,
    readEventSession,
    () => null,
  )
}

type HeaderAccessClusterProps = {
  layout?: "bar" | "sheet"
  onSheetNavigate?: () => void
}

export function HeaderAccessCluster({
  layout = "bar",
  onSheetNavigate,
}: HeaderAccessClusterProps) {
  const pathname = usePathname()
  const session = useEventSession()
  const adminUser = useAdminSession()
  const showAdminEntry = !pathname.startsWith("/admin")

  useEffect(() => {
    getActiveCheckinSessionKind()
  }, [])

  if (adminUser && !session) {
    return (
      <HeaderStaffAccountMenu
        layout={layout}
        onNavigate={onSheetNavigate}
      />
    )
  }

  if (layout === "sheet") {
    if (session) {
      return (
        <HeaderAccountMenu layout="sheet" onNavigate={onSheetNavigate} />
      )
    }

    return (
      <HeaderGuestAccessOptions
        showAdmin={showAdminEntry}
        onNavigate={onSheetNavigate}
      />
    )
  }

  if (session) {
    return <HeaderAccountMenu />
  }

  if (!showAdminEntry) {
    return <HeaderAuth />
  }

  return <HeaderGuestAccessDropdown showAdmin={showAdminEntry} />
}

src/components/shared/header-account-men.content:
"use client"

import Link from "next/link"
import {
  ChevronDown,
  ChevronRight,
  ClipboardList,
  LogOut,
  UserCircle2,
} from "lucide-react"
import { usePathname, useRouter } from "next/navigation"
import { useSyncExternalStore } from "react"
import { Avatar, AvatarFallback, AvatarImage } from "@ui/components/avatar"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@ui/components/dropdown-menu"
import { cn } from "@ui/lib/utils"
import {
  clearEventSession,
  getEventAccountLabel,
  getMyEventsPath,
  getProfilePath,
  isEventAuthLoginPath,
  isEventPortalPath,
  isStudentSession,
  readEventSession,
  subscribeEventSession,
} from "@/lib/event-auth"

function useEventSession() {
  return useSyncExternalStore(
    subscribeEventSession,
    readEventSession,
    () => null,
  )
}

function displayNameOf(session: {
  name?: string | null
  email: string
}): string {
  return session.name?.trim() || session.email
}

function initials(name: string): string {
  const parts = name
    .trim()
    .split(/\s+/)
    .map((p) => p.replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, ""))
    .filter(Boolean)
  if (!parts.length) return "SV"
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase()
}

function UserAvatar({
  name,
  imageUrl,
  className,
}: {
  name: string
  imageUrl: string | null
  className?: string
}) {
  return (
    <span className={cn("relative shrink-0", className)}>
      <Avatar className="size-9 aspect-square after:rounded-lg">
        {imageUrl ? (
          <AvatarImage src={imageUrl} alt="" className="rounded-lg" />
        ) : null}
        <AvatarFallback className="rounded-lg bg-primary/10 text-[11px] font-bold text-primary">
          {initials(name)}
        </AvatarFallback>
      </Avatar>
    </span>
  )
}

type HeaderAccountMenuProps = {
  layout?: "bar" | "sheet"
  onNavigate?: () => void
}

function AccountIdentity({
  name,
  email,
  accountLabel,
}: {
  name: string
  email: string
  accountLabel: string
}) {
  return (
    <div className="min-w-0">
      <p className="truncate text-sm font-semibold text-foreground">{name}</p>
      <p className="mt-0.5 truncate text-xs text-muted-foreground">{email}</p>
      <Badge variant="secondary" className="mt-2 h-5 px-1.5 text-[10px]">
        {accountLabel}
      </Badge>
    </div>
  )
}

function SheetActionLink({
  href,
  icon: Icon,
  label,
  description,
  onNavigate,
}: {
  href: string
  icon: typeof ClipboardList
  label: string
  description?: string
  onNavigate?: () => void
}) {
  return (
    <Link
      href={href}
      onClick={onNavigate}
      className="flex items-center gap-3 rounded-xl border border-border/70 bg-card px-3 py-2.5 transition-colors hover:bg-muted/50"
    >
      <span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-muted text-foreground">
        <Icon className="size-4" aria-hidden />
      </span>
      <span className="min-w-0 flex-1">
        <span className="block text-sm font-medium">{label}</span>
        {description ? (
          <span className="block text-xs text-muted-foreground">{description}</span>
        ) : null}
      </span>
      <ChevronRight className="size-4 shrink-0 text-muted-foreground/60" />
    </Link>
  )
}

export function HeaderAccountMenu({
  layout = "bar",
  onNavigate,
}: HeaderAccountMenuProps) {
  const session = useEventSession()
  const pathname = usePathname()
  const router = useRouter()

  if (!session) return null

  const name = displayNameOf(session)
  const avatarUrl = session.image?.trim() || null
  const student = isStudentSession(session)
  const accountLabel = getEventAccountLabel(session)
  const myEventsPath = getMyEventsPath(session)

  const handleLogout = () => {
    clearEventSession()
    onNavigate?.()
    if (isEventPortalPath(pathname) || isEventAuthLoginPath(pathname)) {
      router.replace("/")
      router.refresh()
      return
    }
    window.location.reload()
  }

  if (layout === "sheet") {
    return (
      <div className="space-y-3 rounded-2xl border border-border/70 bg-muted/15 p-3">
        <div className="flex items-center gap-3 px-1">
          <UserAvatar name={name} imageUrl={avatarUrl} />
          <AccountIdentity
            name={name}
            email={session.email}
            accountLabel={accountLabel}
          />
        </div>
        <div className="grid gap-2">
          <SheetActionLink
            href={myEventsPath}
            icon={ClipboardList}
            label="Sự kiện của tôi"
            description="Đăng ký và check-in QR"
            onNavigate={onNavigate}
          />
          {student ? (
            <SheetActionLink
              href={getProfilePath(session)}
              icon={UserCircle2}
              label="Hồ sơ sinh viên"
              onNavigate={onNavigate}
            />
          ) : null}
          <Button
            type="button"
            variant="outline"
            className="h-10 w-full justify-start gap-2 rounded-xl border-destructive/30 text-destructive hover:bg-destructive/5 hover:text-destructive"
            onClick={handleLogout}
          >
            <LogOut className="size-4" />
            Đăng xuất
          </Button>
        </div>
      </div>
    )
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type="button"
            variant="outline"
            size="sm"
            className={cn(
              "h-12 max-w-[min(100vw-7rem,260px)] gap-2 overflow-hidden rounded-xl border-border/80 bg-card px-2 shadow-sm",
              "hover:border-primary/30 hover:bg-card hover:shadow-md",
            )}
            aria-label="Mở menu tài khoản"
          />
        }
      >
        <UserAvatar name={name} imageUrl={avatarUrl} />
        <span className="hidden min-w-0 flex-1 flex-col items-start leading-none sm:flex">
          <span className="flex w-full min-w-0 items-center gap-1.5">
            <span className="truncate text-sm font-semibold">{name}</span>
          </span>
          <span className="mt-1 truncate text-[11px] text-muted-foreground">
            {accountLabel}
          </span>
        </span>
        <ChevronDown className="size-4 shrink-0 text-muted-foreground/70" />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        sideOffset={8}
        className="w-[min(calc(100vw-1.5rem),300px)] rounded-2xl border border-border/70 p-2 shadow-xl"
      >
        <DropdownMenuGroup>
          <div className="flex items-start gap-3 px-2 py-2">
            <UserAvatar name={name} imageUrl={avatarUrl} />
            <AccountIdentity
              name={name}
              email={session.email}
              accountLabel={accountLabel}
            />
          </div>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuGroup>
          <DropdownMenuLabel className="px-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">
            Cổng sự kiện
          </DropdownMenuLabel>
          <DropdownMenuItem
            className="cursor-pointer gap-2.5 rounded-lg py-2"
            onClick={() => {
              onNavigate?.()
              router.push(myEventsPath)
            }}
          >
            <ClipboardList className="size-4 text-primary" />
            Sự kiện của tôi
          </DropdownMenuItem>
          {student ? (
            <DropdownMenuItem
              className="cursor-pointer gap-2.5 rounded-lg py-2"
              onClick={() => {
                onNavigate?.()
                router.push(getProfilePath(session))
              }}
            >
              <UserCircle2 className="size-4 text-primary" />
              Hồ sơ sinh viên
            </DropdownMenuItem>
          ) : null}
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuGroup>
          <DropdownMenuItem
            variant="destructive"
            className="cursor-pointer gap-2.5 rounded-lg py-2"
            onClick={handleLogout}
          >
            <LogOut className="size-4" />
            Đăng xuất
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

src/components/shared/header-action-tile.content:
"use client"

import Link from "next/link"
import type { LucideIcon } from "lucide-react"
import { cn } from "@ui/lib/utils"

export type HeaderActionTileVariant = "portal" | "staff"

const STRIP_VARIANT: Record<HeaderActionTileVariant, string> = {
  portal:
    "bg-gradient-to-br from-primary via-primary to-primary/80 text-primary-foreground",
  staff:
    "bg-gradient-to-br from-brand-navy via-brand-navy to-brand-navy/85 text-white",
}

export type HeaderActionTileProps = {
  href: string
  icon: LucideIcon
  title: string
  subtitle?: string
  variant: HeaderActionTileVariant
  ariaLabel: string
  inMenu?: boolean
  showStatusDot?: boolean
}

export function HeaderActionTile({
  href,
  icon: Icon,
  title,
  subtitle,
  variant,
  ariaLabel,
  inMenu = false,
  showStatusDot = false,
}: HeaderActionTileProps) {
  return (
    <Link
      href={href}
      className={cn(
        "inline-flex shrink-0",
        inMenu ? "w-full" : undefined,
      )}
      aria-label={ariaLabel}
    >
      <span
        className={cn(
          "group/tile inline-flex items-stretch overflow-hidden rounded-xl border border-border/80 bg-card text-left shadow-sm transition-all duration-200",
          "hover:-translate-y-px hover:border-primary/35 hover:shadow-md",
          "focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-ring/50",
          inMenu ? "h-11 w-full" : "h-9",
        )}
      >
        <span
          className={cn(
            "relative flex w-9 shrink-0 items-center justify-center",
            STRIP_VARIANT[variant],
          )}
        >
          <Icon className="relative size-4" aria-hidden />
          {showStatusDot ? (
            <span
              className="absolute right-1 top-1 size-1.5 rounded-full bg-emerald-400 ring-2 ring-white/90"
              aria-hidden
            />
          ) : null}
        </span>
        <span
          className={cn(
            "flex min-w-0 items-center border-l border-border/70 px-3",
            inMenu ? "flex-1" : "hidden sm:flex",
          )}
        >
          <span className="flex min-w-0 flex-col leading-none">
            <span className="truncate text-sm font-semibold text-foreground">
              {title}
            </span>
            {subtitle ? (
              <span className="mt-0.5 truncate text-[10px] font-medium text-muted-foreground">
                {subtitle}
              </span>
            ) : null}
          </span>
        </span>
      </span>
    </Link>
  )
}

src/components/shared/header-admin-link..content:
"use client"

import { usePathname } from "next/navigation"
import { LayoutDashboard, Shield } from "lucide-react"
import {
  CHECKIN_ADMIN_HOME_PATH,
  CHECKIN_ADMIN_LOGIN_PATH,
} from "@/config/admin/checkin-admin-access"
import { HeaderActionTile } from "@/components/shared/header-action-tile"
import { useAdminSession } from "@/components/shared/use-admin-session"

export function HeaderAdminLink({ inMenu = false }: { inMenu?: boolean }) {
  const pathname = usePathname()
  const adminUser = useAdminSession()

  if (pathname.startsWith("/admin")) return null

  const signedIn = Boolean(adminUser)
  const href = signedIn ? CHECKIN_ADMIN_HOME_PATH : CHECKIN_ADMIN_LOGIN_PATH

  return (
    <HeaderActionTile
      href={href}
      icon={signedIn ? LayoutDashboard : Shield}
      title={signedIn ? "Quản trị" : "Quản trị"}
      subtitle={signedIn ? "Đã đăng nhập" : "Nhân viên · BTC"}
      variant="staff"
      ariaLabel={
        signedIn ? "Vào bảng quản trị sự kiện" : "Đăng nhập quản trị sự kiện"
      }
      inMenu={inMenu}
      showStatusDot={signedIn}
    />
  )
}

src/components/shared/header-auth.tsx.content:
"use client"

import {
  ChevronDown,
  ClipboardList,
  LogIn,
  LogOut,
  UserCircle2,
} from "lucide-react"
import { HeaderActionTile } from "@/components/shared/header-action-tile"
import { Avatar, AvatarFallback, AvatarImage } from "@ui/components/avatar"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@ui/components/dropdown-menu"
import { cn } from "@ui/lib/utils"
import { useSyncExternalStore } from "react"
import { usePathname, useRouter } from "next/navigation"
import {
  buildLoginHref,
  clearEventSession,
  getEventAccountLabel,
  getMyEventsPath,
  getProfilePath,
  isEventAuthLoginPath,
  isEventPortalPath,
  isStudentSession,
  readEventSession,
  subscribeEventSession,
} from "@/lib/event-auth"

function useEventSession() {
  return useSyncExternalStore(
    subscribeEventSession,
    readEventSession,
    () => null
  )
}

function displayNameOf(session: {
  name?: string | null
  email: string
}): string {
  return session.name?.trim() || session.email
}

function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (!parts.length) return "SV"
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase()
}

function UserAvatar({
  name,
  imageUrl,
  className,
  fallbackClassName,
}: {
  name: string
  imageUrl: string | null
  className?: string
  fallbackClassName?: string
}) {
  return (
    <Avatar
      className={cn("size-9 aspect-square shrink-0 after:rounded-lg", className)}
    >
      {imageUrl ? (
        <AvatarImage src={imageUrl} alt="" className="rounded-lg" />
      ) : null}
      <AvatarFallback
        className={cn(
          "rounded-lg bg-primary/10 text-[11px] font-bold text-primary",
          fallbackClassName
        )}
      >
        {initials(name)}
      </AvatarFallback>
    </Avatar>
  )
}

function LoginTriggerLink({ href }: { href: string }) {
  return (
    <HeaderActionTile
      href={href}
      icon={LogIn}
      title="Đăng nhập"
      subtitle="Sinh viên · Khách"
      variant="portal"
      ariaLabel="Đăng nhập để quản lý sự kiện"
    />
  )
}

export function HeaderAuth() {
  const session = useEventSession()
  const pathname = usePathname()
  const router = useRouter()

  if (session) {
    const name = displayNameOf(session)
    const avatarUrl = session.image?.trim() || null
    const student = isStudentSession(session)
    const accountLabel = getEventAccountLabel(session)
    const myEventsPath = getMyEventsPath(session)

    const handleLogout = () => {
      clearEventSession()
      if (isEventPortalPath(pathname) || isEventAuthLoginPath(pathname)) {
        router.replace("/")
        router.refresh()
        return
      }
      window.location.reload()
    }

    return (
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="h-12 min-w-0 max-w-[min(100vw-8rem,280px)] gap-2 overflow-hidden rounded-xl px-2.5 sm:px-3 py-2"
              aria-label="Mở menu tài khoản"
            />
          }
        >
          <UserAvatar name={name} imageUrl={avatarUrl} />
          <div className="hidden min-w-0 flex-1 flex-col items-start gap-0.5 overflow-hidden sm:flex">
            <span className="flex w-full min-w-0 items-center gap-1.5">
              <span className="min-w-0 truncate text-sm font-medium">{name}</span>
              <Badge
                variant="secondary"
                className="h-5 shrink-0 px-1.5 text-[10px]"
              >
                {accountLabel}
              </Badge>
            </span>
            <span className="truncate text-xs text-muted-foreground">
              {session.email}
            </span>
          </div>
          <ChevronDown className="size-4 shrink-0 opacity-60" />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-72 rounded-xl p-2">
          <div className="mb-1 px-2 py-1.5">
            <p className="text-sm font-semibold">{name}</p>
            <p className="text-xs text-muted-foreground">{session.email}</p>
          </div>
          <DropdownMenuSeparator />
          <DropdownMenuGroup>
            <DropdownMenuItem
              className="cursor-pointer gap-2 rounded-lg"
              onClick={() => router.push(myEventsPath)}
            >
              <ClipboardList className="size-4 text-muted-foreground" />
              Sự kiện của tôi
            </DropdownMenuItem>
            {student ? (
              <DropdownMenuItem
                className="cursor-pointer gap-2 rounded-lg"
                onClick={() => router.push(getProfilePath(session))}
              >
                <UserCircle2 className="size-4 text-muted-foreground" />
                Hồ sơ sinh viên
              </DropdownMenuItem>
            ) : null}
          </DropdownMenuGroup>
          <DropdownMenuSeparator />
          <DropdownMenuGroup>
            <DropdownMenuItem
              className="cursor-pointer gap-2 rounded-lg text-destructive focus:text-destructive"
              onClick={handleLogout}
            >
              <LogOut className="size-4" />
              Đăng xuất
            </DropdownMenuItem>
          </DropdownMenuGroup>
        </DropdownMenuContent>
      </DropdownMenu>
    )
  }

  const loginHref = buildLoginHref(pathname || "/")
  return <LoginTriggerLink href={loginHref} />
}

src/components/shared/header-guest-acces.content:
"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import {
  ChevronDown,
  ChevronRight,
  LayoutDashboard,
  LogIn,
  Shield,
} from "lucide-react"
import { Button } from "@ui/components/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@ui/components/dropdown-menu"
import { cn } from "@ui/lib/utils"
import { HeaderAccessOptionCard } from "@/components/shared/header-access-option-card"
import {
  CHECKIN_ADMIN_HOME_PATH,
  CHECKIN_ADMIN_LOGIN_PATH,
} from "@/config/admin/checkin-admin-access"
import { useAdminSession } from "@/components/shared/use-admin-session"
import { buildLoginHref, readEventSession } from "@/lib/event-auth"

type GuestAccessOptionsProps = {
  showAdmin: boolean
  onNavigate?: () => void
  className?: string
}

export function HeaderGuestAccessOptions({
  showAdmin,
  onNavigate,
  className,
}: GuestAccessOptionsProps) {
  const pathname = usePathname()
  const adminUser = useAdminSession()

  const portalHref = buildLoginHref(pathname || "/")
  const portalSignedIn = Boolean(readEventSession())
  const adminSignedIn = Boolean(adminUser)
  const adminHref = adminSignedIn
    ? CHECKIN_ADMIN_HOME_PATH
    : CHECKIN_ADMIN_LOGIN_PATH

  return (
    <div className={cn("grid gap-2", className)}>
      {!portalSignedIn ? (
      <HeaderAccessOptionCard
        href={portalHref}
        icon={LogIn}
        title="Đăng nhập sự kiện"
        subtitle="Sinh viên · Khách"
        variant="portal"
        ariaLabel="Đăng nhập để quản lý sự kiện"
        onClick={onNavigate}
      />
      ) : null}
      {showAdmin && !adminSignedIn ? (
        <HeaderAccessOptionCard
          href={adminHref}
          icon={adminSignedIn ? LayoutDashboard : Shield}
          title={adminSignedIn ? "Tổng quan" : "Đăng nhập quản trị"}
          subtitle="Ban quản trị"
          variant="staff"
          ariaLabel={
            adminSignedIn
              ? "Vào bảng quản trị sự kiện"
              : "Đăng nhập quản trị sự kiện"
          }
          showStatusDot={adminSignedIn}
          onClick={onNavigate}
        />
      ) : null}
    </div>
  )
}

type HeaderGuestAccessDropdownProps = {
  showAdmin: boolean
}

export function HeaderGuestAccessDropdown({
  showAdmin,
}: HeaderGuestAccessDropdownProps) {
  const pathname = usePathname()
  const adminUser = useAdminSession()
  const adminSignedIn = Boolean(adminUser)
  const portalHref = buildLoginHref(pathname || "/")
  const portalSignedIn = Boolean(readEventSession())
  const adminHref = adminSignedIn
    ? CHECKIN_ADMIN_HOME_PATH
    : CHECKIN_ADMIN_LOGIN_PATH

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type="button"
            variant="outline"
            size="sm"
            className={cn(
              "h-10 gap-1.5 rounded-xl border-border/80 bg-card px-3 shadow-sm",
              "hover:border-primary/30 hover:bg-card hover:shadow-md",
            )}
            aria-label="Mở menu đăng nhập"
          />
        }
      >
        <LogIn className="size-4 shrink-0 text-primary" aria-hidden />
        <span className="text-sm font-semibold text-foreground">Đăng nhập</span>
        <ChevronDown className="size-4 shrink-0 text-muted-foreground/70" />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        sideOffset={8}
        className="w-[min(calc(100vw-1.5rem),280px)] rounded-2xl border border-border/70 p-2 shadow-xl"
      >
        <DropdownMenuGroup>
          <DropdownMenuLabel className="px-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">
            Cổng sự kiện
          </DropdownMenuLabel>
          {!portalSignedIn ? (
            <DropdownMenuItem
              className="cursor-pointer gap-2.5 rounded-lg py-2"
              render={<Link href={portalHref} />}
            >
              <LogIn className="size-4 text-primary" aria-hidden />
              <span className="flex min-w-0 flex-1 flex-col items-start gap-0.5">
                <span className="font-medium">Đăng nhập</span>
                <span className="text-xs text-muted-foreground">
                  Sinh viên · Khách
                </span>
              </span>
              <ChevronRight className="ml-auto size-4 text-muted-foreground/50" />
            </DropdownMenuItem>
          ) : null}
        </DropdownMenuGroup>

        {showAdmin && !adminSignedIn ? (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuGroup>
              <DropdownMenuLabel className="px-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">
                Ban quản trị
              </DropdownMenuLabel>
              <DropdownMenuItem
                className="cursor-pointer gap-2.5 rounded-lg py-2"
                render={<Link href={adminHref} />}
              >
                {adminSignedIn ? (
                  <LayoutDashboard
                    className="size-4 text-brand-navy"
                    aria-hidden
                  />
                ) : (
                  <Shield className="size-4 text-brand-navy" aria-hidden />
                )}
                <span className="flex min-w-0 flex-1 flex-col items-start gap-0.5">
                  <span className="font-medium">
                    {adminSignedIn ? "Tổng quan" : "Đăng nhập quản trị"}
                  </span>
                  <span className="text-xs text-muted-foreground">
                    Ban quản trị
                  </span>
                </span>
                <ChevronRight className="ml-auto size-4 text-muted-foreground/50" />
              </DropdownMenuItem>
            </DropdownMenuGroup>
          </>
        ) : null}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

src/components/shared/header-staff-accou.content:
"use client"

import Link from "next/link"
import { ChevronDown, LayoutDashboard, LogOut, UserCircle2 } from "lucide-react"
import { usePathname, useRouter } from "next/navigation"
import { Avatar, AvatarFallback, AvatarImage } from "@ui/components/avatar"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@ui/components/dropdown-menu"
import { cn } from "@ui/lib/utils"
import {
  CHECKIN_ADMIN_HOME_PATH,
  CHECKIN_ADMIN_PROFILE_PATH,
} from "@/config/admin/checkin-admin-access"
import { useAdminSession } from "@/components/shared/use-admin-session"
import {
  ADMIN_SESSION_EVENT,
  clearAdminSession,
} from "@/lib/admin/auth-session"

function displayNameOf(user: {
  name?: string | null
  email: string
}): string {
  return user.name?.trim() || user.email
}

function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (!parts.length) return "BQ"
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase()
}

type HeaderStaffAccountMenuProps = {
  layout?: "bar" | "sheet"
  onNavigate?: () => void
}

export function HeaderStaffAccountMenu({
  layout = "bar",
  onNavigate,
}: HeaderStaffAccountMenuProps) {
  const adminUser = useAdminSession()
  const pathname = usePathname()
  const router = useRouter()

  if (!adminUser) return null

  const name = displayNameOf(adminUser)
  const avatarUrl = adminUser.image?.trim() || null
  const inAdmin = pathname.startsWith("/admin")

  const handleLogout = () => {
    clearAdminSession()
    window.dispatchEvent(new Event(ADMIN_SESSION_EVENT))
    onNavigate?.()
    if (pathname.startsWith("/admin")) {
      router.replace("/")
      router.refresh()
      return
    }
    window.location.reload()
  }

  if (layout === "sheet") {
    return (
      <div className="space-y-3 rounded-2xl border border-border/70 bg-muted/15 p-3">
        <div className="flex items-center gap-3 px-1">
          <Avatar className="size-9 aspect-square after:rounded-lg">
            {avatarUrl ? (
              <AvatarImage src={avatarUrl} alt="" className="rounded-lg" />
            ) : null}
            <AvatarFallback className="rounded-lg bg-brand-navy/10 text-[11px] font-bold text-brand-navy">
              {initials(name)}
            </AvatarFallback>
          </Avatar>
          <div className="min-w-0">
            <p className="truncate text-sm font-semibold text-foreground">
              {name}
            </p>
            <p className="mt-0.5 truncate text-xs text-muted-foreground">
              {adminUser.email}
            </p>
            <Badge variant="secondary" className="mt-2 h-5 px-1.5 text-[10px]">
              Ban quản trị
            </Badge>
          </div>
        </div>
        <div className="grid gap-2">
          {!inAdmin ? (
            <Link
              href={CHECKIN_ADMIN_HOME_PATH}
              onClick={onNavigate}
              className="flex items-center gap-3 rounded-xl border border-brand-navy/20 bg-brand-navy/[0.04] px-3 py-2.5"
            >
              <LayoutDashboard className="size-4 text-brand-navy" />
              <span className="text-sm font-medium">Tổng quan</span>
            </Link>
          ) : null}
          <Link
            href={CHECKIN_ADMIN_PROFILE_PATH}
            onClick={onNavigate}
            className="flex items-center gap-3 rounded-xl border border-border/70 px-3 py-2.5"
          >
            <UserCircle2 className="size-4 text-brand-navy" />
            <span className="text-sm font-medium">Hồ sơ của tôi</span>
          </Link>
          <Button
            type="button"
            variant="outline"
            className="h-10 w-full justify-start gap-2 rounded-xl border-destructive/30 text-destructive hover:bg-destructive/5 hover:text-destructive"
            onClick={handleLogout}
          >
            <LogOut className="size-4" />
            Đăng xuất
          </Button>
        </div>
      </div>
    )
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type="button"
            variant="outline"
            size="sm"
            className={cn(
              "h-12 max-w-[min(100vw-7rem,260px)] gap-2 overflow-hidden rounded-xl border-border/80 bg-card px-2 shadow-sm",
              "hover:border-primary/30 hover:bg-card hover:shadow-md",
            )}
            aria-label="Mở menu ban quản trị"
          />
        }
      >
        <Avatar className="size-9 aspect-square after:rounded-lg">
          {avatarUrl ? (
