"use client"

import type { Dispatch, SetStateAction } from "react"
import { XCircle } from "lucide-react"
import { toast } from "sonner"
import type { AdminDataTableBulkAction } from "@ui/components/data-table"
import {
  cancelMyEventRegistration,
  type MyRegisteredEvent,
} from "@/lib/my-registered-events"
import type { MyRegisteredEventRow } from "./types"
import { canCancelRegistrationRow } from "./utils"

export function buildMyRegisteredEventsBulkActions({
  setRows,
  reload,
}: {
  setRows: Dispatch<SetStateAction<MyRegisteredEvent[]>>
  reload: (options?: { silent?: boolean }) => Promise<void>
}): AdminDataTableBulkAction<MyRegisteredEventRow>[] {
  return [
    {
      id: "cancel",
      label: "Hủy đăng ký",
      variant: "destructive",
      icon: <XCircle className="size-4" />,
      disabled: (selectedRows) =>
        selectedRows.length === 0 ||
        selectedRows.some((row) => !canCancelRegistrationRow(row)),
      confirm: {
        title: "Hủy các đăng ký đã chọn?",
        description:
          "Chỉ hủy được khi còn trong thời gian đăng ký, chưa check-in và sự kiện chưa bắt đầu.",
        confirmLabel: "Hủy đăng ký",
        destructive: true,
      },
      onAction: async (selectedRows) => {
        if (selectedRows.some((row) => !canCancelRegistrationRow(row))) {
          toast.error(
            "Có đăng ký đã chọn không thể hủy (ngoài thời gian đăng ký, đã check-in hoặc sự kiện đã bắt đầu)."
          )
          return
        }
        if (selectedRows.length === 0) {
          toast.error("Vui lòng chọn ít nhất một đăng ký có thể hủy.")
          return
        }

        try {
          const updatedRows = await Promise.all(
            selectedRows.map((row) => cancelMyEventRegistration(row.id))
          )
          const updatedById = new Map(
            updatedRows.map((row) => [row.id, row] as const)
          )
          setRows((current) =>
            current.map((item) => updatedById.get(item.id) ?? item)
          )
          toast.success(
            selectedRows.length === 1
              ? "Đã hủy đăng ký sự kiện."
              : `Đã hủy ${selectedRows.length} đăng ký sự kiện.`
          )
        } catch (err) {
          toast.error(
            err instanceof Error ? err.message : "Không thể hủy đăng ký."
          )
          await reload({ silent: true })
          throw err
        }
      },
    },
  ]
}

"use client"

import { useMemo } from "react"
import { useRouter } from "next/navigation"
import { CalendarDays, RefreshCw } from "lucide-react"
import { Alert, AlertDescription, AlertTitle } from "@ui/components/alert"
import {
  AdminListPageHeader,
  AdminPageSection,
} from "@ui/components/admin"
import { Button } from "@ui/components/button"
import { canCancelMyRegistration } from "@/lib/my-registered-events"
import { MyRegisteredEventsTable } from "./_table"
import { useMyRegisteredEvents } from "./_query"
import { getMyRegisteredEventColumns } from "./columns"
import { buildMyRegisteredEventsBulkActions } from "./my-registered-events-bulk-actions"
import { MyRegisteredEventsStatCards } from "./my-registered-events-stat-cards"
import { eventHref } from "./utils"

function MyRegisteredEventsPageInner() {
  const router = useRouter()
  const {
    session,
    rows,
    setRows,
    loading,
    error,
    load,
    stats,
    cancellingId,
    cancelRegistration,
  } = useMyRegisteredEvents()

  const exportGeneratedAt = useMemo(
    () =>
      new Intl.DateTimeFormat("vi-VN", {
        dateStyle: "medium",
        timeStyle: "short",
      }).format(new Date()),
    []
  )

  const actionHandlers = useMemo(
    () => ({
      onView: (row: (typeof rows)[number]) => {
        router.push(eventHref(row))
      },
      onCancel: async (row: (typeof rows)[number]) => {
        if (!canCancelMyRegistration(row)) return
        await cancelRegistration(row)
      },
      cancellingId,
    }),
    [cancelRegistration, cancellingId, router]
  )

  const columns = useMemo(
    () => getMyRegisteredEventColumns({ actionHandlers }),
    [actionHandlers]
  )

  const bulkActions = useMemo(
    () => buildMyRegisteredEventsBulkActions({ setRows, reload: load }),
    [load, setRows]
  )

  if (!session) {
    return null
  }

  return (
    <AdminPageSection className="space-y-6">
      <AdminListPageHeader
        icon={CalendarDays}
        title="Sự kiện của tôi"
        subtitle="Danh sách đăng ký, trạng thái check-in và hủy đăng ký khi còn thời hạn."
        actions={
          <Button
            variant="outline"
            onClick={() => void load()}
            className="h-11 font-bold"
          >
            <RefreshCw
              className={`mr-2 size-4 ${loading ? "animate-spin" : ""}`}
            />
            Làm mới
          </Button>
        }
      />

      <MyRegisteredEventsStatCards stats={stats} loading={loading} />

      {error ? (
        <Alert variant="destructive">
          <AlertTitle>Không thể tải dữ liệu</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : null}

      <MyRegisteredEventsTable
        rows={rows}
        columns={columns}
        loading={loading}
        session={session}
        exportGeneratedAt={exportGeneratedAt}
        bulkActions={bulkActions}
      />
    </AdminPageSection>
  )
}

export function MyRegisteredEventsPage() {
  return <MyRegisteredEventsPageInner />
}

"use client"

import { ExternalLink, Loader2, XCircle } from "lucide-react"
import {
  DataTableRowActionsMenu,
  type DataTableRowActionItem,
} from "@ui/components/data-table"
import { getCancelRegistrationState } from "@/lib/my-registered-events"
import type { MyRegisteredEventRow } from "./types"

export type MyRegisteredEventRowActionHandlers = {
  onView: (row: MyRegisteredEventRow) => void
  onCancel: (row: MyRegisteredEventRow) => void | Promise<void>
  cancellingId?: string | null
}

function buildRowActions(
  row: MyRegisteredEventRow,
  handlers: MyRegisteredEventRowActionHandlers,
): DataTableRowActionItem[] {
  const cancelState = getCancelRegistrationState(row)
  const isCancelling = handlers.cancellingId === row.id

  const actions: DataTableRowActionItem[] = [
    {
      key: "view",
      label: "Xem sự kiện",
      hint: "Mở trang chi tiết và vé điện tử",
      icon: <ExternalLink className="size-4" />,
      onClick: () => handlers.onView(row),
      group: "primary",
    },
  ]

  if (cancelState.allowed || isCancelling) {
    actions.push({
      key: "cancel",
      label: "Hủy đăng ký",
      hint: cancelState.allowed
        ? "Chỉ hủy khi còn trong thời gian đăng ký"
        : cancelState.reason,
      icon: isCancelling ? (
        <Loader2 className="size-4 animate-spin" />
      ) : (
        <XCircle className="size-4" />
      ),
      disabled: !cancelState.allowed || isCancelling,
      title: !cancelState.allowed ? cancelState.reason : undefined,
      menuVariant: "destructive",
      group: "danger",
      confirm: cancelState.allowed
        ? {
            title: "Hủy đăng ký sự kiện?",
            description: `Bạn sẽ hủy đăng ký «${row.event.title}». Thao tác này không thể hoàn tác.`,
            confirmLabel: "Hủy đăng ký",
            destructive: true,
          }
        : false,
      onClick: () => handlers.onCancel(row),
    })
  }

  return actions
}

export function MyRegisteredEventRowActions({
  row,
  handlers,
}: {
  row: MyRegisteredEventRow
  handlers: MyRegisteredEventRowActionHandlers
}) {
  const actions = buildRowActions(row, handlers)
  const busy = handlers.cancellingId === row.id

  return (
    <div className="flex w-full justify-center">
      <DataTableRowActionsMenu
        actions={actions}
        busy={busy}
        triggerLabel="Thao tác đăng ký sự kiện"
        groups={{
          primary: { label: "Sự kiện" },
          danger: { label: "Hủy đăng ký", sublabel: true },
        }}
      />
    </div>
  )
}

